// Wix on the site owner's own API key: every REST method Wix documents for a site (stores, eCommerce, bookings, CMS,
// blog, contacts, forms, members, events, pricing plans, invoices, coupons, media…) plus the account-level ones (sites,
// domains). actions.json is generated by `bun scripts/openapi-actions.ts wix` from Wix's markdown docs.
// An API key isn't tied to one site, so the key carries the site's id (and the account's, for account-level calls).
import { AppsError } from "../../types";
import type { OwnApp } from "../index";
import { type Api, call, specActions } from "../openapi";

// "<api key> <site id> [<account id>]", as pasted on one line
export function parseKey(key: string) {
  const [apiKey, siteId, accountId] = key.trim().split(/\s+/);
  if (!apiKey || !siteId) throw new AppsError("paste the API key, then a space and the site id (and, for account-wide work, a space and the account id)");
  return { apiKey, siteId, accountId };
}

const base = { name: "Wix", base: "https://www.wixapis.com", tokenHelp: "manage.wix.com/account/api-keys" };
// Wix wants one of the two ids, never both. An account-wide call on a key with no account id tries the site's,
// and Wix says why if that isn't enough.
const site: Api = { ...base, auth: (key) => ({ Authorization: parseKey(key).apiKey, "wix-site-id": parseKey(key).siteId }) };
const account: Api = {
  ...base,
  auth: (key): Record<string, string> => {
    const { apiKey, siteId, accountId } = parseKey(key);
    return accountId ? { Authorization: apiKey, "wix-account-id": accountId } : { Authorization: apiKey, "wix-site-id": siteId };
  },
};

const FILE = new URL("./actions.json", import.meta.url);
const actions = await specActions(FILE, site);
const { actions: generated } = (await Bun.file(FILE).json()) as { actions: { name: string; account?: boolean; send: any }[] };
for (const a of generated) if (a.account) actions[a.name]!.run = (i: Record<string, unknown>, key: string) => call(account, key, a.send, i);

export const wix: OwnApp = {
  app: "wix",
  name: "Wix",
  logo: "/logos/wix.svg",
  keyField: {
    label: "API key, site id (and account id)",
    help: "manage.wix.com/account/api-keys → Generate API Key, tick the site and every permission Emplio should have. The site id is in your site's dashboard address (after /dashboard/), the account id on the same API keys page. Paste them on one line, separated by spaces: API key, site id, then the account id if Emplio should also manage your sites and domains.",
    placeholder: "IST.eyJ... 1a2b3c4d-site-id 9f8e7d6c-account-id",
  },
  // the site's own name; a wrong key gets a 401, a key without this site a 403 or 404
  async check(key) {
    parseKey(key);
    const got = (await call(site, key, { method: "GET", path: "/site-properties/v4/properties", query: [], headers: [] }, {})) as { properties?: { siteDisplayName?: string; businessName?: string } };
    return got.properties?.siteDisplayName || got.properties?.businessName || undefined;
  },
  actions,
};
